        {!isUndefined(id) && !isUndefined(disputeKitAddress) && DisputeKitOverviewExtraInfoComponent ? (
          <DisputeKitOverviewExtraInfoComponent disputeId={id} {...{ disputeKitAddress, currentRoundIndex }} />
