# Adding a New Dispute Kit

> NOTE: Also use this file as a checklist for new DK addition PRs

## File Structure

```
dispute-kits/
├── disputeKits.ts                 # DisputeKits enum (on-chain IDs)
├── types.ts                       # DisputeKitConfig, Features, Group
├── registry.ts                    # DISPUTE_KIT_REGISTRY — single source of truth
├── disputeFeature.ts              # Feature selection utils
├── prepareArbitratorExtradata.ts  # Creation data types + encoders
└── index.ts                       # Barrel exports
```

## Steps

### 1. Enum — `disputeKits.ts`

Add a value matching the **on-chain dispute kit ID**:

```ts
export enum DisputeKits {
  // ...
  YourNewKit = 7,
}
```

TypeScript will now error everywhere until you handle the new kit.

### 2. Registry — `registry.ts`

Add the entry. Reuse existing components where possible:

```ts
[DisputeKits.YourNewKit]: {
  id: DisputeKits.YourNewKit,
  displayName: "Your New Kit",
  address: disputeKitYourNewKitAddress[chainId],
  OverviewExtraInfo: undefined,
  VotingComponent: ClassicVotingComponent,
  AppealComponent: ClassicAppealComponent,
  disputeKitAbi: disputeKitYourNewKitAbi,
  hasAutomaticVoteReveal: false,
  featureSets: [[Features.ClassicVote, Features.YourNewFeature]],
},
```

### 3. Features (if new) — `types.ts` + `disputeFeature.ts`

Add to `Features` enum in `types.ts`, then to the relevant group in `disputeFeature.ts`.
Create a UI component in `components/DisputeFeatures/Features/` and register it in `Features/index.tsx`.

### 4. Initial feature selection — `disputeFeature.ts`

Add a case in `resolveInitialFeatureSet()`. The exhaustive switch will error if you skip this.

### 5. Creation data (if any) — `prepareArbitratorExtradata.ts`

- Add type to `DisputeKitDataMap` (`AssertAllKits` errors if missing)
- Add encoder to `DisputeKitDataEncoder` (or `undefined` if no additional extra data)
- **MAKE SURE TO NOT LEAVE IT `undefined` IN CASE THE KIT REQUIRES ADDITIONAL EXTRADATA.** Define the Encoder accordingly in ./prepareArbitratorExtradata, along with an appropriate test for it.

### 6. Builders — `actions/{commit,reveal,vote,fundAppeal}/builders/`

Each has a `Record<DisputeKits, Builder>` map — TypeScript errors for the missing key. Reuse an existing builder if the logic matches.

### 7. Deployment filtering (if needed) — `disputeFeature.ts`

Update `getDisputeKitsForDeployment()` to exclude the kit on specific deployments.

### 8. Subgraph

Add a data source block in `subgraph/core/subgraph.template.yaml`. This is separate from the web registry.

## What TypeScript Catches

Adding a new enum value triggers compile errors in:

- `DISPUTE_KIT_REGISTRY` — missing entry
- `DisputeKitDataMap` — missing key
- `DisputeKitDataEncoder` — missing key
- `resolveInitialFeatureSet` — unhandled case
- All 4 builder maps in `actions/` — missing key

Fix all of these and the kit is integrated.

## Gotchas

- **Enum value = on-chain ID.**
- **`featureSets[0]` is the default.** For multi-set kits, add selection logic in `resolveInitialFeatureSet`.
- **Builders are intentionally separate** from the registry. They own their own ABI + address for testability.
- **Subgraph queries use `ClassicRound` fragments.** If your kit has a different round structure, you'll need new queries.
- **Dispute Kit Encoder** These are required by the DK to handle the encoding of extradata on top of the classic arbitrator extradata. MAKE SURE TO NOT LEAVE IT `undefined` IN CASE THE KIT REQUIRES ADDITIONAL EXTRADATA. Define the Encoder accordingly in ./prepareArbitratorExtradata, along with an appropriate test for it.
import React, { useMemo } from "react";

import { useParams } from "react-router-dom";
import { useAccount } from "wagmi";

import { useDrawQuery } from "hooks/queries/useDrawQuery";
import { useVotingContext } from "hooks/useVotingContext";
import { Bytes32Hash } from "utils/crypto/hashVote";

import { useDisputeDetailsQuery } from "queries/useDisputeDetailsQuery";

import { DisputeKitVotingProps } from "src/dispute-kits";

import Commit from "./Commit";
import Reveal from "./Reveal";
import Vote from "./Vote";

const Classic: React.FC<DisputeKitVotingProps> = ({ arbitrable, setIsOpen, disputeKitId }) => {
  const { id } = useParams();
  const { address } = useAccount();
  const { data: disputeData } = useDisputeDetailsQuery(id);
  const { data: drawData } = useDrawQuery(address?.toLowerCase(), id, disputeData?.dispute?.currentRound.id);
  const { isHiddenVotes, isCommitPeriod, commit, commited } = useVotingContext();
  const voteIDs = useMemo(() => drawData?.draws?.map((draw) => draw.voteIDNum) as string[], [drawData]);

  return id && isHiddenVotes ? (
    isCommitPeriod && !commited ? (
      <Commit {...{ arbitrable, setIsOpen, voteIDs, disputeKitId }} />
    ) : (
      <Reveal
        {...{
          arbitrable,
          setIsOpen,
          voteIDs,
          isRevealPeriod: !isCommitPeriod,
          disputeKitId,
          commit: commit as Bytes32Hash,
        }}
      />
    )
  ) : (
    <Vote {...{ arbitrable, setIsOpen, voteIDs, disputeKitId }} />
  );
};

export default Classic;
import React, { useMemo } from "react";

import { useParams } from "react-router-dom";
import { useAccount } from "wagmi";

import { useDrawQuery } from "hooks/queries/useDrawQuery";
import { useVotingContext } from "hooks/useVotingContext";

import { DisputeKitVotingProps } from "src/dispute-kits";

import ShutterCommit from "./Commit";
import Reveal from "./Reveal";

const Shutter: React.FC<DisputeKitVotingProps> = ({
  arbitrable,
  setIsOpen,
  dispute,
  currentPeriodIndex,
  disputeKitId,
}) => {
  const { id } = useParams();
  const { address } = useAccount();
  const { data: drawData } = useDrawQuery(address?.toLowerCase(), id, dispute?.currentRound.id);
  const { isCommitPeriod, isVotingPeriod, commit, commited } = useVotingContext();
  const voteIDs = useMemo(() => drawData?.draws?.map((draw) => draw.voteIDNum) as string[], [drawData]);

  const shouldShowCommit = id && isCommitPeriod && !commited;
  const shouldShowReveal = id && isVotingPeriod;

  return (
    <>
      {shouldShowCommit && (
        <ShutterCommit {...{ arbitrable, setIsOpen, voteIDs, dispute, currentPeriodIndex, disputeKitId }} />
      )}
      {shouldShowReveal && <Reveal {...{ setIsOpen, voteIDs, disputeKitId, arbitrable, commit }} />}
    </>
  );
};

export default Shutter;
import { buildCommitTxn } from "./builders";
import type { CommitContext } from "./context";
import type { CommitParams } from "./params";

/**
 * Builds a commit transaction and sends it to the relevant DisputeKit contract.
 *
 * @param params  Parameters for the commit transaction. Must include a `disputeKitId` field
 *                corresponding to a `DisputeKits` value.
 * @param context Execution context, usually including chain info, account data,
 *                and a `walletClient` to send the transaction.
 *
 * @returns The transaction hash.
 *
 * @dev Internally, this calls {@link buildCommitTxn} to construct the transaction
 * (ABI, functionName, args, etc.) and then executes it via the `walletClient`
 * provided in `context`.
 */
export async function executeCommit(params: CommitParams, context: CommitContext) {
  const tx = await buildCommitTxn(params, context);
  const { walletClient } = context;
  return walletClient.writeContract(tx);
}
import { Abi, ContractFunctionName, WriteContractParameters } from "viem";

export type ActionTx<TAbi extends Abi, TFn extends ContractFunctionName<TAbi>> = WriteContractParameters<TAbi, TFn>;

export interface ActionBuilder<TParams, TContext, TDeps, TAbi extends Abi, TFn extends ContractFunctionName<TAbi>> {
  /**
   * Builder-level dependency defaults.
   *
   * Allows a specific builder to:
   * - Provide defaults for dependencies it uniquely requires
   *   (e.g. an `encrypt` helper used only by shutter builders)
   * - Override any global default dependency if necessary
   *   (e.g. a specialized storage implementation)
   *
   * These dependencies are shallow-merged with the global defaults
   * and any call-site overrides at build time.
   *
   * Call-site overrides passed to `build(...)` always take precedence.
   */
  builderDeps?: Partial<TDeps>;
  build(params: TParams, context: TContext, deps: TDeps): Promise<ActionTx<TAbi, TFn>>;
}

/**
 * Typed action builder factory.
 *
 * This helper fixes the `params`, `context`, and `deps` types for a family of
 * action builders, so individual builders only need to specify the contract ABI
 * and function name, which also inferred from return object of builder.build.
 *
 * Dependency resolution happens at build time via a shallow merge, in the
 * following order (later entries take precedence):
 *
 * 1. Global default dependencies provided to this factory
 * 2. Builder-level default dependencies (`builder.builderDeps`)
 * 3. Call-site dependency overrides passed to `build(...)`
 *
 * This allows:
 * - Shared builder dependencies to be defined once globally
 * - Individual builders to declare or override defaults for their own needs
 * - Callers (e.g. tests) to selectively override any dependency
 *
 * The resolved dependency object is guaranteed (at the type level) to satisfy
 * `TDeps` and is passed to the builder implementation as a fully populated
 * dependency set.
 *
 * @typeParam TParams   Parameters coming from the caller (usually UI input)
 * @typeParam TContext  Execution context (e.g. chain, account)
 * @typeParam TDeps     Dependency set for the builder (storage, etc.)
 *
 * @param defaultDeps   Global default dependencies shared by all builders
 *
 * @returns A function that accepts a builder definition and returns an object
 *          exposing a `build` function with dependency resolution applied.
 */
export function defineActionBuilder<TParams, TContext, TDeps extends object>(defaultDeps: TDeps) {
  return function <TAbi extends Abi, TFn extends ContractFunctionName<TAbi>>(
    builder: ActionBuilder<TParams, TContext, TDeps, TAbi, TFn>
  ) {
    return {
      build(params: TParams, context: TContext, overrideDeps?: Partial<TDeps>) {
        const resolvedDeps = {
          ...defaultDeps,
          ...builder?.builderDeps,
          ...overrideDeps,
        } satisfies TDeps;

        return builder.build(params, context, resolvedDeps);
      },
    };
  };
}

