import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useWalletClient, usePublicClient, useAccount } from "wagmi";

import { executeVote } from "actions/vote/execute";
import { VoteParams } from "actions/vote/params";

import { errorToast, wrapWithToast } from "utils/wrapWithToast";

import { isUndefined } from "src/utils";

type VoteMutation = VoteParams;
export function useVote(onSuccess?: () => void) {
  const queryClient = useQueryClient();

  const { data: walletClient } = useWalletClient();
  const publicClient = usePublicClient();
  const { address: account, chain } = useAccount();

  return useMutation({
    mutationFn: async (params: VoteMutation) => {
      if (isUndefined(account)) {
        throw new Error("Account not defined. Is the wallet connected?");
      }
      if (isUndefined(chain)) {
        throw new Error("Chain not defined. Is the wallet connected?");
      }

      if (isUndefined(walletClient)) {
        throw new Error("WalletClient not defined. Is the wallet connected?");
      }

      if (isUndefined(publicClient)) {
        throw new Error("PublicClient not defined. Is the wallet connected?");
      }

      const executeTxn = () => executeVote(params, { chain, account, walletClient });

      const result = await wrapWithToast(executeTxn, publicClient);

      return result;
    },
    onSuccess: (res) => {
      if (!res.status) return;
      onSuccess?.();
      queryClient.invalidateQueries({ queryKey: ["useDrawQuery"] });
    },
    onError: (err: unknown) => {
      console.error(err);
      if (err instanceof Error) {
        errorToast(err.message);
      }
    },
  });
}
import React, { useCallback, useMemo, useState } from "react";
import styled from "styled-components";

import { useParams } from "react-router-dom";
import type { Address } from "viem";

import { useVote } from "hooks/useVote";

import { useDisputeDetailsQuery } from "queries/useDisputeDetailsQuery";

import { VoteParams } from "src/actions/vote/params";
import { DisputeKits } from "src/dispute-kits";
import { isUndefined } from "src/utils";

import OptionsContainer from "../OptionsContainer";

const Container = styled.div`
  width: 100%;
  height: auto;
`;

interface IVote {
  arbitrable: Address;
  voteIDs: string[];
  setIsOpen: (val: boolean) => void;
  disputeKitId: DisputeKits;
}

const Vote: React.FC<IVote> = ({ arbitrable, voteIDs, setIsOpen, disputeKitId }) => {
  const { id } = useParams();
  const parsedDisputeID = useMemo(() => BigInt(id ?? 0), [id]);
  const parsedVoteIDs = useMemo(() => voteIDs.map((voteID) => BigInt(voteID)), [voteIDs]);
  const { data: disputeData } = useDisputeDetailsQuery(id);
  const currentRoundIndex = disputeData?.dispute?.currentRoundIndex;
  const [justification, setJustification] = useState("");

  const { mutateAsync: vote } = useVote(() => {
    setIsOpen(true);
  });

  const handleVote = useCallback(
    async (voteOption: bigint) => {
      if (isUndefined(currentRoundIndex)) {
        return;
      }

      await vote({
        disputeId: parsedDisputeID,
        voteIds: parsedVoteIDs,
        choice: voteOption,
        salt: BigInt(currentRoundIndex),
        justification,
        disputeKitId,
      } as VoteParams);
    },
    [currentRoundIndex, justification, parsedVoteIDs, parsedDisputeID, vote, disputeKitId]
  );

  return (
    <Container>
      <OptionsContainer {...{ arbitrable, justification, setJustification, handleSelection: handleVote }} />
    </Container>
  );
};

export default Vote;
