import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import styled, { DefaultTheme, useTheme } from "styled-components";

import { useTranslation } from "react-i18next";
import { useParams } from "react-router-dom";
import { Hash, type TransactionReceipt } from "viem";
import { usePublicClient } from "wagmi";

import { type _TimelineItem1, Button } from "@kleros/ui-components-library";

import { DEFAULT_CHAIN } from "consts/chains";
import {
  klerosCoreAddress,
  useSimulateKlerosCoreSetStake,
  useWriteKlerosCoreSetStake,
  useSimulatePnkIncreaseAllowance,
  useWritePnkIncreaseAllowance,
} from "hooks/contracts/generated";
import { useLockOverlayScroll } from "hooks/useLockOverlayScroll";
import { usePnkData } from "hooks/usePNKData";
import { isUndefined } from "utils/index";
import { parseWagmiError } from "utils/parseWagmiError";
import { refetchWithRetry } from "utils/refecthWithRetry";

import { useCourtDetails } from "queries/useCourtDetails";

import { EnsureChain } from "components/EnsureChain";

import StakeWithdrawPopup from "./StakeWithdrawPopup";
import { getStakeSteps, StakeSteps } from "./StakeWithdrawPopup/stakeSteps";

export enum ActionType {
  allowance = "allowance",
  stake = "stake",
  withdraw = "withdraw",
}

const Container = styled.div`
  display: flex;
  gap: 8px;
  flex-direction: column;
`;

type Steps = [_TimelineItem1, ..._TimelineItem1[]];
interface IActionButton {
  amount: string;
  parsedAmount: bigint;
  action: ActionType;
  setAmount: (arg0: string) => void;
  setErrorMsg: (msg?: string) => void;
  isPopupOpen: boolean;
  setIsPopupOpen: (arg0: boolean) => void;
}

const StakeWithdrawButton: React.FC<IActionButton> = ({
  amount,
  parsedAmount,
  action,
  setErrorMsg,
  setAmount,
  isPopupOpen,
  setIsPopupOpen,
}) => {
  const { t } = useTranslation();
  const { id } = useParams();
  const theme = useTheme();
  const [isSuccess, setIsSuccess] = useState(false);
  const [popupStepsState, setPopupStepsState] = useState<Steps>();
  const controllerRef = useRef<AbortController | null>(null);
  useLockOverlayScroll(isPopupOpen);

  const { balance, jurorBalance, allowance, refetchAllowance } = usePnkData({ courtId: id });
  const { data: courtDetails } = useCourtDetails(id);
  const publicClient = usePublicClient();

  const isStaking = action === ActionType.stake;
  const isAllowance = isStaking && !isUndefined(allowance) && allowance < parsedAmount;

  const targetStake = useMemo(() => {
    if (jurorBalance) {
      if (isAllowance) {
        return parsedAmount;
      } else if (isStaking) {
        return jurorBalance[2] + parsedAmount;
      } else {
        return jurorBalance[2] - parsedAmount;
      }
    }
    return 0n;
  }, [jurorBalance, parsedAmount, isAllowance, isStaking]);

  const {
    data: increaseAllowanceConfig,
    isLoading: isSimulatingAllowance,
    error: allowanceError,
  } = useSimulatePnkIncreaseAllowance({
    query: {
      enabled:
        isAllowance &&
        !isUndefined(targetStake) &&
        !isUndefined(allowance) &&
        !isUndefined(balance) &&
        parsedAmount <= balance,
    },
    args: [klerosCoreAddress[DEFAULT_CHAIN.id], BigInt(targetStake ?? 0) - BigInt(allowance ?? 0)],
  });

  const { writeContractAsync: increaseAllowance } = useWritePnkIncreaseAllowance();

  const {
    data: setStakeConfig,
    error: setStakeError,
    isLoading: isSimulatingSetStake,
    refetch: refetchSetStake,
  } = useSimulateKlerosCoreSetStake({
    query: {
      enabled:
        !isUndefined(targetStake) &&
        !isUndefined(id) &&
        parsedAmount !== 0n &&
        targetStake >= 0n &&
        !isAllowance &&
        Boolean(isStaking ? balance && parsedAmount <= balance : jurorBalance && parsedAmount <= jurorBalance[2]),
    },
    args: [BigInt(id ?? 0), targetStake],
  });
  const { writeContractAsync: setStake } = useWriteKlerosCoreSetStake();

  const updatePopupState = (signal: AbortSignal, state: Steps) => {
    if (signal.aborted) return;
    setPopupStepsState(state);
  };

  const handleStake = useCallback(
    (signal: AbortSignal, config?: typeof setStakeConfig, approvalHash?: Hash) => {
      if (signal.aborted) return;
      const isWithdraw = action === ActionType.withdraw;
      const requestData = config?.request ?? setStakeConfig?.request;
      const commonArgs: [string, DefaultTheme, (key: string) => string, Hash | undefined] = [
        amount,
        theme,
        t,
        approvalHash,
      ];

      if (requestData && publicClient) {
        updatePopupState(
          signal,
          getStakeSteps(isWithdraw ? StakeSteps.WithdrawInitiate : StakeSteps.StakeInitiate, ...commonArgs)
        );

        setStake(requestData)
          .then(async (hash) => {
            if (signal.aborted) return;
            updatePopupState(
              signal,
              getStakeSteps(isWithdraw ? StakeSteps.WithdrawPending : StakeSteps.StakePending, ...commonArgs, hash)
            );
            await publicClient.waitForTransactionReceipt({ hash, confirmations: 2 }).then((res: TransactionReceipt) => {
              if (signal.aborted) return;
              const status = res.status === "success";
              if (status) {
                updatePopupState(
                  signal,
                  getStakeSteps(
                    isWithdraw ? StakeSteps.WithdrawConfirmed : StakeSteps.StakeConfirmed,
                    ...commonArgs,
                    hash
                  )
                );
                setIsSuccess(true);
              } else
                updatePopupState(
                  signal,
                  getStakeSteps(isWithdraw ? StakeSteps.WithdrawFailed : StakeSteps.StakeFailed, ...commonArgs, hash)
                );
            });
          })
          .catch((err) => {
            updatePopupState(
              signal,
              getStakeSteps(
                isWithdraw ? StakeSteps.WithdrawFailed : StakeSteps.StakeFailed,
                ...commonArgs,
                undefined,
                err
              )
            );
          });
      } else {
        updatePopupState(
          signal,
          getStakeSteps(
            StakeSteps.StakeFailed,
            ...commonArgs,
            undefined,
            new Error("Simulation Failed. Please restart the process.")
          )
        );
      }
    },
    [setStake, setStakeConfig, publicClient, amount, theme, action, t]
  );

  const handleClick = useCallback(() => {
    setIsPopupOpen(true);
    controllerRef.current = new AbortController();
    const signal = controllerRef.current.signal;
    const commonArgs: [string, DefaultTheme, (key: string) => string] = [amount, theme, t];

    if (isAllowance && increaseAllowanceConfig && publicClient) {
      updatePopupState(signal, getStakeSteps(StakeSteps.ApproveInitiate, ...commonArgs));

      increaseAllowance(increaseAllowanceConfig.request)
        .then(async (hash) => {
          if (signal.aborted) return;
          updatePopupState(signal, getStakeSteps(StakeSteps.ApprovePending, ...commonArgs, hash));

          await publicClient
            .waitForTransactionReceipt({ hash, confirmations: 2 })
            .then(async (res: TransactionReceipt) => {
              if (signal.aborted) return;
              const status = res.status === "success";
              if (status) {
                await refetchAllowance();
                const refetchData = await refetchWithRetry(refetchSetStake);
                // check for a relatively new error with react/tanstack-query:
                // https://github.com/TanStack/query/issues/8209
                if (!refetchData?.data)
                  updatePopupState(
                    signal,
                    getStakeSteps(
                      StakeSteps.ApproveFailed,
                      ...commonArgs,
                      hash,
                      undefined,
                      new Error("Something went wrong. Please restart the process.")
                    )
                  );
                else {
                  handleStake(signal, refetchData.data, hash);
                }
              } else updatePopupState(signal, getStakeSteps(StakeSteps.ApproveFailed, ...commonArgs, hash));
            });
        })
        .catch((err) => {
          updatePopupState(signal, getStakeSteps(StakeSteps.ApproveFailed, ...commonArgs, undefined, undefined, err));
        });
    } else {
      handleStake(signal);
    }
  }, [
    increaseAllowance,
    increaseAllowanceConfig,
    handleStake,
    isAllowance,
    theme,
    publicClient,
    amount,
    refetchAllowance,
    refetchSetStake,
    setIsPopupOpen,
    t,
  ]);

  useEffect(() => {
    if (isPopupOpen) return;
    if (setStakeError || allowanceError) {
      setErrorMsg(parseWagmiError(setStakeError || allowanceError));
    }
  }, [setStakeError, setErrorMsg, targetStake, allowanceError, isPopupOpen]);

  const isDisabled = useMemo(() => {
    if (
      parsedAmount == 0n ||
      (action === ActionType.stake &&
        courtDetails &&
        jurorBalance &&
        parsedAmount !== 0n &&
        (isUndefined(courtDetails.court?.minStake) ||
          jurorBalance[2] + parsedAmount < BigInt(courtDetails.court.minStake)))
    )
      return true;
    if (isAllowance) {
      return isUndefined(increaseAllowanceConfig) || isSimulatingAllowance || !isUndefined(allowanceError);
    }
    return isUndefined(setStakeConfig) || isSimulatingSetStake || !isUndefined(setStakeError);
  }, [
    parsedAmount,
    increaseAllowanceConfig,
    isSimulatingAllowance,
    setStakeConfig,
    isSimulatingSetStake,
    setStakeError,
    allowanceError,
    isAllowance,
    action,
    courtDetails,
    jurorBalance,
  ]);

  const closePopup = () => {
    setErrorMsg(undefined);
    setIsPopupOpen(false);
    setIsSuccess(false);
    setAmount("");
    setPopupStepsState(undefined);
    if (controllerRef.current) {
      controllerRef.current.abort();
    }
  };

  return (
    <EnsureChain>
      <Container>
        <Button
          data-testId="stake-withdraw-button"
          text={isStaking ? t("buttons.stake") : t("buttons.withdraw")}
          isLoading={isPopupOpen || isSimulatingAllowance || isSimulatingSetStake}
          disabled={isDisabled || isSimulatingAllowance || isSimulatingSetStake}
          onClick={handleClick}
        />
        {isPopupOpen && <StakeWithdrawPopup {...{ action, closePopup, amount, steps: popupStepsState, isSuccess }} />}
      </Container>
    </EnsureChain>
  );
};

export default StakeWithdrawButton;
import React from "react";
import styled, { DefaultTheme } from "styled-components";

import { _TimelineItem1, StateProp } from "@kleros/ui-components-library";

import CheckIcon from "svgs/icons/check-circle-outline.svg";

import Spinner from "components/Spinner";
import TxnHash from "components/TxnHash";

const StyledLabel = styled.label`
  color: ${({ theme }) => theme.secondaryPurple};
`;

const PartyContainer = styled.div`
  display: flex;
  gap: 8px;
`;

export enum StakeSteps {
  ApproveInitiate,
  ApprovePending,
  ApproveFailed,
  StakeInitiate,
  StakeConfirmed,
  StakePending,
  StakeFailed,
  WithdrawInitiate,
  WithdrawPending,
  WithdrawConfirmed,
  WithdrawFailed,
}

const createApprovalSteps = (
  theme: DefaultTheme,
  variant: string,
  state: StateProp["state"],
  amount: string,
  hash: `0x${string}` | undefined,
  error: any,
  t: (key: string) => string
): [_TimelineItem1, ..._TimelineItem1[]] => {
  const party = () => {
    if (variant === "refused") return hash ? <TxnHash hash={hash} variant="error" /> : <></>;
    return state === "loading" ? (
      <></>
    ) : (
      <PartyContainer>
        {hash && <TxnHash hash={hash} variant="pending" />}
        <Spinner />
      </PartyContainer>
    );
  };
  return [
    {
      title: t("wallet.approve_in_wallet"),
      subtitle: error ? (error?.shortMessage ?? error?.message) : t("wallet.pnk_spending"),
      rightSided: true,
      variant,
      state,
      party: party(),
    },
    {
      title: t("wallet.stake_in_wallet"),
      subtitle: "",
      rightSided: true,
      variant: theme.secondaryPurple,
      party: <StyledLabel>{amount} PNK</StyledLabel>,
      state: "disabled",
    },
  ];
};

const createStakeSteps = (
  theme: DefaultTheme,
  variant: string,
  state: StateProp["state"],
  amount: string,
  approvalHash: `0x${string}` | undefined,
  stakeHash: `0x${string}` | undefined,
  error: any,
  isStake: boolean,
  t: (key: string) => string
): [_TimelineItem1, ..._TimelineItem1[]] => {
  const party = () => {
    if (["refused", "accepted"].includes(variant))
      return stakeHash ? <TxnHash hash={stakeHash} variant={variant === "refused" ? "error" : "success"} /> : <></>;
    return state === "loading" ? (
      <StyledLabel>{amount} PNK</StyledLabel>
    ) : (
      <PartyContainer>
        {stakeHash && <TxnHash hash={stakeHash} variant="pending" />}
        <Spinner />
      </PartyContainer>
    );
  };
  return isStake
    ? [
        {
          title: t("wallet.approve_in_wallet"),
          subtitle: t("wallet.pnk_spending"),
          rightSided: true,
          variant: theme.success,
          party: approvalHash ? <TxnHash hash={approvalHash} variant="success" /> : <></>,
          Icon: CheckIcon,
        },
        {
          title: t("wallet.stake_in_wallet"),
          subtitle: error ? (error?.shortMessage ?? error?.message) : "",
          rightSided: true,
          variant,
          state,
          party: party(),
          Icon: variant === "accepted" ? CheckIcon : undefined,
        },
      ]
    : [
        {
          title: t("wallet.unstake_in_wallet"),
          subtitle: error ? (error?.shortMessage ?? error?.message) : "",
          rightSided: true,
          variant,
          state,
          party: party(),
          Icon: variant === "accepted" ? CheckIcon : undefined,
        },
      ];
};

export const getStakeSteps = (
  stepType: StakeSteps,
  amount: string,
  theme: DefaultTheme,
  t: (key: string) => string,
  approvalHash?: `0x${string}`,
  stakeHash?: `0x${string}`,
  error?: any
): [_TimelineItem1, ..._TimelineItem1[]] => {
  switch (stepType) {
    case StakeSteps.ApproveInitiate:
      return createApprovalSteps(theme, theme.secondaryPurple, "loading", amount, approvalHash, error, t);

    case StakeSteps.ApprovePending:
      return createApprovalSteps(theme, theme.secondaryPurple, "active", amount, approvalHash, error, t);
    case StakeSteps.ApproveFailed:
      return createApprovalSteps(theme, "refused", "active", amount, approvalHash, error, t);
    case StakeSteps.StakeInitiate:
      return createStakeSteps(theme, theme.secondaryPurple, "loading", amount, approvalHash, stakeHash, error, true, t);
    case StakeSteps.StakePending:
      return createStakeSteps(theme, theme.secondaryPurple, "active", amount, approvalHash, stakeHash, error, true, t);
    case StakeSteps.StakeFailed:
      return createStakeSteps(theme, "refused", "active", amount, approvalHash, stakeHash, error, true, t);
    case StakeSteps.StakeConfirmed:
      return createStakeSteps(theme, "accepted", "active", amount, approvalHash, stakeHash, error, true, t);
    case StakeSteps.WithdrawInitiate:
      return createStakeSteps(
        theme,
        theme.secondaryPurple,
        "loading",
        amount,
        approvalHash,
        stakeHash,
        error,
        false,
        t
      );
    case StakeSteps.WithdrawPending:
      return createStakeSteps(theme, theme.secondaryPurple, "active", amount, approvalHash, stakeHash, error, false, t);
    case StakeSteps.WithdrawConfirmed:
      return createStakeSteps(theme, "accepted", "active", amount, approvalHash, stakeHash, error, false, t);
    default:
      return createStakeSteps(theme, "refused", "active", amount, approvalHash, stakeHash, error, false, t);
  }
};

