import { useAccount } from "wagmi";

import { DEFAULT_CHAIN } from "consts/chains";

import { REFETCH_INTERVAL } from "src/consts";
import { isUndefined } from "src/utils";

import {
  klerosCoreAddress,
  useReadPnkAllowance,
  useReadPnkBalanceOf,
  useReadSortitionModuleGetJurorBalance,
} from "./contracts/generated";

interface UsePnkDataParams {
  courtId?: string;
}

/**
 * @description hook to provide user's pnk data. (pnk balance, pnk allowance, jurorBalance for provided courtId)
 * @param param0 optional court Id to fetch juror balance for. Defaults to 0
 */
export const usePnkData = ({ courtId = "0" }: UsePnkDataParams) => {
  const { address } = useAccount();
  const queryConfig = {
    enabled: !isUndefined(address),
    refetchInterval: REFETCH_INTERVAL,
  };

  const { data: balance } = useReadPnkBalanceOf({
    query: queryConfig,
    args: [address!],
  });

  const { data: jurorBalance } = useReadSortitionModuleGetJurorBalance({
    query: queryConfig,
    args: [address!, BigInt(courtId)],
  });

  const { data: allowance, refetch: refetchAllowance } = useReadPnkAllowance({
    query: queryConfig,
    args: [address!, klerosCoreAddress[DEFAULT_CHAIN.id]],
  });

  return { balance, jurorBalance, allowance, refetchAllowance };
};
import { REFETCH_INTERVAL } from "consts/index";
import { useReadSortitionModule } from "hooks/contracts/generated";

export const useSortitionModulePhase = () => {
  // eslint-disable-next-line
  // @ts-ignore
  return useReadSortitionModule({ functionName: "phase", query: { refetchInterval: REFETCH_INTERVAL } });
};

export const useReadSortitionModuleDelayedStakeReadIndex = () => {
  return useReadSortitionModule({
    // eslint-disable-next-line
    // @ts-ignore
    functionName: "delayedStakeReadIndex",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};

export const useReadSortitionModuleDelayedStakeWriteIndex = () => {
  return useReadSortitionModule({
    // eslint-disable-next-line
    // @ts-ignore
    functionName: "delayedStakeWriteIndex",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};

export const useReadSortitionModuleLastPhaseChange = () => {
  return useReadSortitionModule({
    // eslint-disable-next-line
    // @ts-ignore
    functionName: "lastPhaseChange",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};

export const useReadSortitionModuleMaxDrawingTime = () => {
  return useReadSortitionModule({
    // eslint-disable-next-line
    // @ts-ignore
    functionName: "maxDrawingTime",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};

export const useReadSortitionModuleMinStakingTime = () => {
  return useReadSortitionModule({
    // eslint-disable-next-line
    // @ts-ignore
    functionName: "minStakingTime",
    query: { refetchInterval: REFETCH_INTERVAL },
  });
};
import { useMemo } from "react";

import { parseUnits } from "viem";

export function useParsedAmount(amount: `${number}`): bigint {
  return useMemo(() => parseUnits(amount, 18), [amount]);
}
