import { toast, ToastPosition, Theme } from "react-toastify";
import { PublicClient, TransactionReceipt } from "viem";
import { parseWagmiError } from "./parseWagmiError";
export const OPTIONS = {
  position: "top-center" as ToastPosition,
  autoClose: 5000,
  hideProgressBar: false,
  closeOnClick: true,
  pauseOnHover: true,
  draggable: true,
  progress: undefined,
  theme: "colored" as Theme,
};
type WrapWithToastReturnType = {
  status: boolean;
  result?: TransactionReceipt;
};
export const infoToast = (message: string) => toast.info(message, OPTIONS);
export const successToast = (message: string) => toast.success(message, OPTIONS);
export const errorToast = (message: string) => toast.error(message, OPTIONS);
export async function wrapWithToast(
  contractWrite: () => Promise<`0x${string}`>,
  publicClient: PublicClient
): Promise<WrapWithToastReturnType> {
  toast.info("Transaction initiated", OPTIONS);
  return await contractWrite()
    .then(
      async (hash) =>
        await publicClient.waitForTransactionReceipt({ hash, confirmations: 2 }).then((res: TransactionReceipt) => {
          const status = res.status === "success";
          if (status) toast.success("Transaction mined!", OPTIONS);
          else toast.error("Transaction reverted!", OPTIONS);
          return { status, result: res };
        })
    )
    .catch((error) => {
      toast.error(parseWagmiError(error), OPTIONS);
      return { status: false };
    });
}
export async function catchShortMessage(promise: Promise<any>) {
  return await promise.catch((error) => toast.error(parseWagmiError(error), OPTIONS));
}
import { Address, Hash } from "viem";
import { Roles } from "@kleros/kleros-app";
import { DEFAULT_CHAIN } from "consts/chains";
export const isUndefined = (maybeObject: any): maybeObject is undefined | null =>
  typeof maybeObject === "undefined" || maybeObject === null;
/**
 * Checks if a string is empty or contains only whitespace.
 */
export const isEmpty = (str: string): boolean => str.trim() === "";
export const getTxnExplorerLink = (hash: Hash) => `${DEFAULT_CHAIN?.blockExplorers?.default.url}/tx/${hash}`;
export const getAddressExplorerLink = (address: Address) =>
  `${DEFAULT_CHAIN?.blockExplorers?.default.url}/address/${address}`;
type Role = {
  name: string;
  restriction: {
    maxSize: number;
    allowedMimeTypes: string[];
  };
};
export const getFileUploaderMsg = (
  role: Roles,
  roleRestrictions?: Role[],
  t?: (key: string, params?: any) => string
) => {
  if (!roleRestrictions) return;
  const restrictions = roleRestrictions.find(
    (supportedRoles) => Roles[supportedRoles.name as keyof typeof Roles] === role
  );
  if (!restrictions) return;
  const typesString = restrictions.restriction.allowedMimeTypes
    .map((type) => {
      const [prefix, suffix] = type.split("/");
      if (!suffix) return prefix ?? null;
      return suffix === "*" ? prefix : suffix;
    })
    .join(", ");
  const maxSizeMB = (restrictions.restriction.maxSize / (1024 * 1024)).toFixed(2);
  if (t) {
    return t("forms.messages.allowed_file_types", { types: typesString, maxSize: maxSizeMB });
  }
  return `Allowed file types: [${typesString}], Max allowed size: ${maxSizeMB} MB.`;
};
import { toast } from "react-toastify";
import { OPTIONS as toastOptions } from "utils/wrapWithToast";
let timeoutId: NodeJS.Timeout;
export const debounceErrorToast = (msg: string) => {
  if (timeoutId) clearTimeout(timeoutId);
  timeoutId = setTimeout(() => {
    toast.error(msg, toastOptions);
  }, 5000);
};
import { css, DefaultTheme, FlattenInterpolation, ThemeProps } from "styled-components";
export const MAX_WIDTH_LANDSCAPE = "1400px";
export const BREAKPOINT_LANDSCAPE = 900;
export const landscapeStyle = (styleFn: () => FlattenInterpolation<ThemeProps<DefaultTheme>>) => css`
  @media (min-width: ${BREAKPOINT_LANDSCAPE}px) {
    ${() => styleFn()}
  }
`;
/**
 * @description this func applies repsonsiveness to a css property, the value will range from minSize to maxSize
 * @param minSize the minimum value of the property
 * @param maxSize max value of the property
 * @param minScreen the min screen width at which the property will be at minSize
 * @param maxScreen the max screen width at which the property will be at maxSize
 *
 */
export const responsiveSize = (minSize: number, maxSize: number, minScreen: number = 375, maxScreen: number = 1250) =>
  `calc(
    ${minSize}px + 
    (${maxSize} - ${minSize}) * 
    (min(max(100vw, ${minScreen}px), ${maxScreen}px) - ${minScreen}px) / (${maxScreen - minScreen})
  )`;
import { css, DefaultTheme, FlattenInterpolation, ThemeProps } from "styled-components";
export const BREAKPOINT_PORTRAIT = 600;
export const portraitStyle = (styleFn: () => FlattenInterpolation<ThemeProps<DefaultTheme>>) => css`
  @media (min-width: ${BREAKPOINT_PORTRAIT}px) {
    ${() => styleFn()}
  }
`;
