import { test as base } from "@playwright/test";
import { Hex, recoverMessageAddress } from "viem";

import { MOCK_IPFS_HASH } from "../utils/dispute";
import { createTestJwt } from "../utils/jwt";

// mocking atlas apis
export const test = base.extend<{
  mockAtlas: () => Promise<void>;
}>({
  mockAtlas: [
    async ({ page }, use) => {
      await page.route("*/**/graphql", async (route, request) => {
        const body = request.postDataJSON();
        const operation = body?.operationName;

        // GetNonce
        if (operation === "GetNonce") {
          return route.fulfill({
            status: 200,
            contentType: "application/json",
            body: JSON.stringify({
              data: {
                nonce: "0x1234567890",
              },
            }),
          });
        }

        // Login
        if (operation === "Login") {
          const signature = body.variables.signature! as Hex;
          const message = body.variables.message! as string;
          const address = await recoverMessageAddress({ message, signature });

          const accessToken = await createTestJwt({
            address,
          });

          return route.fulfill({
            status: 200,
            contentType: "application/json",
            body: JSON.stringify({
              data: {
                login: {
                  accessToken,
                },
              },
            }),
          });
import { Abi, Address } from "viem";

import {
  disputeResolverAbi,
  disputeResolverAddress,
  klerosCoreAbi,
  klerosCoreAddress,
  pnkAbi,
  pnkAddress,
  sortitionModuleAbi,
  sortitionModuleAddress,
} from "hooks/contracts/generated";

import { DEFAULT_CHAIN } from ".";

// Contract addresses for default chain
// for future , if we want to add devnet facing tests , will need changes
const chainId = DEFAULT_CHAIN.id as keyof typeof disputeResolverAddress;
